# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Timekeeping reservation routes: who may call them" do
  include_context "timekeeping entry writes"

  # Acceptance: "A service request off the allowlist or for another company is
  # refused, and a user token never reaches these routes".
  # Issue: "An anonymous or user-delegated request never gets it."
  it "refuses a user token, a service without the operation and another company's service on all five routes and writes nothing" do
    arrange = timekeeping_arrange
    company = arrange.company
    other_company = arrange.company
    all_routes = %w[prepare commit abort mark_billed detach_entries]
    owner_token = arrange.token_for(arrange.user(company:, role: "owner"))
    no_operations = arrange.service_identity(company:, name: "reporting", operations: [])
    foreign_service = arrange.service_identity(company: other_company, name: "invoice-boundary", operations: all_routes)
    user = arrange.user(company:, role: "employee")
    project = arrange.project(company:)
    free_entry = arrange.entry(company:, user:, project:)
    billable = arrange.reserved_entry(company:, invoice_id: 501, state: "committed")
    agent_entry = arrange.entry(company:, user:, project:, agent_id: 77)
    generation = arrange.current_generation
    paths = {
      "prepare" => ["/v1/companies/#{company}/reservations/prepare",
                    { "invoice_id" => 502, "disposition" => "active", "entries" => [free_entry] }],
      "commit" => ["/v1/companies/#{company}/reservations/commit", { "invoice_id" => 501 }],
      "abort" => ["/v1/companies/#{company}/reservations/abort", { "invoice_id" => 501 }],
      "mark_billed" => ["/v1/companies/#{company}/invoices/501/mark-billed", {}],
      "detach_entries" => ["/v1/companies/#{company}/agents/77/detach-entries", {}]
    }
    expected = { owner_token => 403, no_operations => 403, foreign_service => 404 }
    before_counts = [Reservation.count, AuditEvent.count, OutboxSnapshot.count, ServiceIdempotencyReceipt.count]

    paths.each do |route, (path, body)|
      expected.each do |credential, status|
        post path, params: body.merge("operation_id" => SecureRandom.uuid, "generation" => generation).to_json,
                   headers: { "Authorization" => "Bearer #{credential}", "Content-Type" => "application/json" }

        expect([route, status, response.status]).to eq([route, status, status])
      end
    end

    expect([Reservation.count, AuditEvent.count, OutboxSnapshot.count, ServiceIdempotencyReceipt.count]).to eq(before_counts)
    expect(Entry.find(billable).bill_status).to eq("unbilled")
    expect(Entry.find(agent_entry).agent_id).to eq(77)
    expect(Reservation.where(entry_id: free_entry).count).to eq(0)
  end
end
